create table if not exists public.club_results (
 id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, season_id uuid not null references public.club_seasons(id) on delete cascade, fixture_id uuid not null unique references public.club_fixtures(id) on delete cascade, home_score integer not null check(home_score>=0), away_score integer not null check(away_score>=0), player_of_match text, match_report text, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.club_goals (
 id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, season_id uuid not null references public.club_seasons(id) on delete cascade, fixture_id uuid not null references public.club_fixtures(id) on delete cascade, player_id uuid references public.club_players(id) on delete set null, player_name text not null, minute integer check(minute between 1 and 130), video_timestamp text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists idx_club_results_org_season on public.club_results(organisation_id,season_id);
create index if not exists idx_club_goals_org_season on public.club_goals(organisation_id,season_id);
alter table public.club_results enable row level security; alter table public.club_goals enable row level security;
drop policy if exists club_results_member_all on public.club_results; create policy club_results_member_all on public.club_results for all to authenticated using(exists(select 1 from public.organisation_memberships om where om.organisation_id=club_results.organisation_id and om.user_id=auth.uid())) with check(exists(select 1 from public.organisation_memberships om where om.organisation_id=club_results.organisation_id and om.user_id=auth.uid()));
drop policy if exists club_goals_member_all on public.club_goals; create policy club_goals_member_all on public.club_goals for all to authenticated using(exists(select 1 from public.organisation_memberships om where om.organisation_id=club_goals.organisation_id and om.user_id=auth.uid())) with check(exists(select 1 from public.organisation_memberships om where om.organisation_id=club_goals.organisation_id and om.user_id=auth.uid()));
drop policy if exists club_results_public_select on public.club_results; create policy club_results_public_select on public.club_results for select to anon,authenticated using(published and exists(select 1 from public.organisations o where o.id=club_results.organisation_id and o.active=true));
drop policy if exists club_goals_public_select on public.club_goals; create policy club_goals_public_select on public.club_goals for select to anon,authenticated using(exists(select 1 from public.organisations o join public.club_fixtures f on f.organisation_id=o.id where o.id=club_goals.organisation_id and o.active=true and f.id=club_goals.fixture_id and f.published=true));
